//! A snapshot of `crate::schema`'s mark table as it was at 3d09071, for the
//! frozen serializer (see `super`). The live table is generated by
//! tools/schemagen and may change; this copy never does.

#![allow(dead_code)]

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MarkKind {
    Bold,
    Italic,
    Code,
    Strike,
    Underline,
    Link,
}

impl MarkKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Bold => "bold",
            Self::Italic => "italic",
            Self::Code => "code",
            Self::Strike => "strike",
            Self::Underline => "underline",
            Self::Link => "link",
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct MarkMarkdownMeta {
    pub delimiter: &'static str,
    pub open_tag: &'static str,
    pub close_tag: &'static str,
    pub no_nesting: bool,
}

pub fn mark_serialization(kind: MarkKind) -> MarkMarkdownMeta {
    match kind {
        MarkKind::Bold => MarkMarkdownMeta {
            delimiter: "**",
            open_tag: "",
            close_tag: "",
            no_nesting: false,
        },
        MarkKind::Italic => MarkMarkdownMeta {
            delimiter: "*",
            open_tag: "",
            close_tag: "",
            no_nesting: false,
        },
        MarkKind::Code => MarkMarkdownMeta {
            delimiter: "`",
            open_tag: "",
            close_tag: "",
            no_nesting: true,
        },
        MarkKind::Strike => MarkMarkdownMeta {
            delimiter: "~~",
            open_tag: "",
            close_tag: "",
            no_nesting: false,
        },
        MarkKind::Underline => MarkMarkdownMeta {
            delimiter: "",
            open_tag: "<u>",
            close_tag: "</u>",
            no_nesting: false,
        },
        MarkKind::Link => MarkMarkdownMeta {
            delimiter: "",
            open_tag: "",
            close_tag: "",
            no_nesting: false,
        },
    }
}
